-- BASELINE OF A NEW, EMPTY COUNTRY DATABASE. Migrations 129 to 145, as one file.
--
-- GENERATED by scripts/ulke-temel-uret.mjs from lib/db/ulke/gocler.json. DO NOT EDIT BY HAND: change or add a
-- migration, add it to that list, and run the script again. The commented source of every statement below is the
-- migration file named above it.
--
-- WHAT IT IS FOR. One database per country. A new country's own database is created empty, and this file is run on
-- it ONCE. It creates every table, rule, function and the recordings bucket a country build needs, and the ledger
-- that records which migrations the database holds (129 to 145, one row each). Migrations written after this
-- file was generated are then run one by one, as files.
--
-- WHERE IT MAY RUN. On a database whose `public` schema holds no table at all. It checks that itself, first, and
-- refuses with an error otherwise: it cannot be run twice, and it cannot be run on a database that is in use.
-- It is one transaction: it is applied completely or not at all.
--
-- It expects what every new project of the database provider brings: the roles anon, authenticated and service_role,
-- the sign-in tables and functions (auth.users, auth.uid(), auth.jwt()) and the storage tables (storage.buckets,
-- storage.objects, storage.foldername()).

begin;
set local lock_timeout = '4s';

do $$
declare n integer;
begin
  select count(*) into n
    from pg_class c join pg_namespace s on s.oid = c.relnamespace
   where s.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'f');
  if n > 0 then
    raise exception 'baseline refused: the public schema of this database already holds % table(s). This file is for a NEW, EMPTY country database and is run once.', n;
  end if;
end $$;

-- ── the ledger (lib/db/ulke/defter.sql) ──
create table if not exists public.schema_migrations (
  version text primary key,
  filename text not null,
  checksum text,
  applied_at timestamptz,
  backfilled boolean not null default false,
  note text
);

alter table public.schema_migrations enable row level security;
revoke all on table public.schema_migrations from anon, authenticated;

-- ── 129_davet_kodlari.sql ──
create table if not exists public.davet_kodlari (
  kod_hash text primary key check (kod_hash ~ '^[0-9a-f]{64}$'),
  ulke text not null check (ulke ~ '^[a-z]{2}$'),
  azami_kullanim integer not null default 1 check (azami_kullanim > 0),
  kullanim integer not null default 0 check (kullanim >= 0),
  son_gecerlilik timestamptz,
  aciklama text,
  created_at timestamptz not null default now(),
  son_kullanim_at timestamptz,
  constraint davet_kodlari_kullanim_siniri check (kullanim <= azami_kullanim)
);

alter table public.davet_kodlari enable row level security;
revoke all on table public.davet_kodlari from anon, authenticated;

create or replace function public.davet_kodu_kullan(p_hash text, p_ulke text)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  n integer;
begin
  update public.davet_kodlari
     set kullanim = kullanim + 1, son_kullanim_at = now()
   where kod_hash = p_hash
     and ulke = p_ulke
     and kullanim < azami_kullanim
     and (son_gecerlilik is null or son_gecerlilik > now());
  get diagnostics n = row_count;
  return n = 1;
end $$;

create or replace function public.davet_kodu_iade(p_hash text, p_ulke text)
returns void language sql security definer set search_path = public as $$
  update public.davet_kodlari set kullanim = greatest(kullanim - 1, 0) where kod_hash = p_hash and ulke = p_ulke;
$$;

revoke execute on function public.davet_kodu_kullan(text, text) from public, anon, authenticated;
revoke execute on function public.davet_kodu_iade(text, text) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.davet_kodu_kullan(text, text) to service_role;
    grant execute on function public.davet_kodu_iade(text, text) to service_role;
  end if;
end $$;

insert into schema_migrations (version, filename, checksum, applied_at, backfilled, note)
values ('129', '129_davet_kodlari.sql', null, now(), false,
  'NOTYA-ULKE-01: invitation codes (hash only, one country each) for countries whose sign-up is not open yet; atomic use / give-back functions bound to the country')
on conflict (version) do nothing;

-- ── 130_hekim_dil_tercihleri.sql ──
create or replace function public.ulke_oturum_ulkesi() returns text
language sql stable set search_path = public as $$
  select coalesce(auth.jwt() -> 'app_metadata' ->> 'country', '')
$$;

create table if not exists public.ulke_hesaplari (
  id uuid primary key references auth.users(id) on delete cascade,
  ulke text not null check (ulke ~ '^[a-z]{2}$'),
  full_name text not null default '',
  ui_language text not null check (ui_language ~ '^[a-z]{2,3}(-[A-Z][a-z]{3})?(-[A-Z]{2})?$'),
  saat_dilimi text check (saat_dilimi is null or (char_length(saat_dilimi) <= 64 and saat_dilimi ~ '^[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)*$')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ulke_hesaplari_ulke_id_tekil unique (ulke, id)
);

create or replace function public.ulke_hesaplari_ulke_kilidi() returns trigger
language plpgsql as $$
begin
  if new.ulke is distinct from old.ulke then
    raise exception 'ulke_hesaplari.ulke is set when the account is created and never changes' using errcode = '23514';
  end if;
  return new;
end $$;

create trigger ulke_hesaplari_ulke_kilidi
  before update of ulke on public.ulke_hesaplari
  for each row execute function public.ulke_hesaplari_ulke_kilidi();

alter table public.ulke_hesaplari enable row level security;

create policy "ulke hesabi kendi satiri" on public.ulke_hesaplari
  for select to authenticated using (id = auth.uid() and ulke = public.ulke_oturum_ulkesi());

revoke all on table public.ulke_hesaplari from anon, authenticated;
grant select on table public.ulke_hesaplari to authenticated;

create table if not exists public.hekim_dil_tercihleri (
